mod irregular;
mod laws;
mod paradigms;
mod relations;
mod rules;
mod spellings;
mod stems;

pub use paradigms::Conjugation;

use flexion::{Candidate, Grammar, Known, Reading};
use std::borrow::Cow;

/// Each cell's place in a paradigm.
#[allow(dead_code)]
pub mod cell {
    pub const VERB_INF: u16 = 0;
    pub const VERB_3SG: u16 = 1;
    pub const VERB_PAST: u16 = 2;
    pub const VERB_PRP: u16 = 3;
    pub const VERB_PP: u16 = 4;
}

/// The grammar: paradigms, the rules choosing one, irregular forms.
pub static GRAMMAR: Grammar<'static, Conjugation> = Grammar {
    orthography: crate::orthography::ORTHOGRAPHY,
    cells: 5,
    lemma_cell: Some(0),
    capitalized: false,
    paradigms: Cow::Borrowed(&paradigms::CONJUGATIONS),
    paradigm: rules::CONJUGATION,
    relations: Cow::Borrowed(&relations::RELATIONS),
    feature: None,
    compound: None,
    kept: Cow::Borrowed(&[]),
    prefixes: None,
    heads: flexion::Heads {
        least: None,
        not: Cow::Borrowed(&[]),
        words: Cow::Borrowed(heads::HEADS),
    },
    accent: None,
    laws: Some(laws::LAWS),
    spellings: Cow::Borrowed(spellings::SPELLINGS),
    marks: None,
    slots: Cow::Borrowed(&stems::SLOTS),
    tables: Cow::Borrowed(&stems::TABLES),
    irregular: irregular::IRREGULAR,
    smoothing: 2.0,
    sharpness: 1.0,
    trust: flexion::Trust {
        regular: 1.0,
        unsettled: 0.98941743,
        unattested: 1.0,
    },
};

/// A verb form: which cell of its conjugation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// A verb form.
    Form(crate::VerbForm),
}

impl Cell {
    /// Its place in a paradigm: its group's first cell, then its values
    /// counted in order, the last fastest.
    pub const fn index(self) -> usize {
        match self {
            Cell::Form(verb_form) => cell::VERB_INF as usize + verb_form as usize,
        }
    }
}

impl From<crate::VerbForm> for Cell {
    fn from(verb_form: crate::VerbForm) -> Self {
        Cell::Form(verb_form)
    }
}

/// A verb to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Verb<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
}

impl<'w> Verb<'w> {
    /// The verb `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Verb {
            lemma,
            given: Vec::new(),
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    fn known(&self) -> Known<'_> {
        Known {
            forms: &self.given,
            inherent: &[],
            full: false,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The conjugations it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn conjugation(&self) -> Vec<Reading<'static, 'static, Conjugation>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
